// =====================================================
// Ping-Ping's database (SQLite) - follows SRS Section 6.1
// One file: data/pingpings.db
//
// Tables (SRS 6.1):  users, products, qr_codes, stock_in, stock_out,
//                    purchase_confirmations, expiration_records, activity_logs
// Extra table:       roles  (the SRS "users.role_id" needs something to point to)
// Reports (SRS):     generated by SQL views  report_inventory,
//                    report_stock_movements, report_expiration
// =====================================================
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

// SQLite is built into Node.js (22.13 or newer), so nothing extra needs to be installed.
let DatabaseSync;
try {
  ({ DatabaseSync } = require("node:sqlite"));
} catch (e) {
  console.error("This server needs Node.js 22.13 or newer (SQLite is built in).");
  console.error("Your Node.js version is " + process.version + ". Please install the latest LTS from https://nodejs.org");
  process.exit(1);
}

const SCHEMA_VERSION = 2;
const NEAR_EXPIRY_DAYS = 7;          // same rule as the website
const SESSION_HOURS = 12;
const BACKUPS_TO_KEEP = 14;

let db;
const paths = {};

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

// ---------- Small helpers ----------
function nowIso() { return new Date().toISOString(); }

function pad(n) { return String(n).padStart(2, "0"); }

function localDay(d = new Date()) {
  return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
}

function stamp(d = new Date()) {
  return localDay(d).replace(/-/g, "") + "-" + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());
}

function toInt(v, label) {
  const n = Number(v);
  if (v === "" || v === null || v === undefined || !Number.isInteger(n)) throw new HttpError(400, label + " must be a whole number.");
  return n;
}

function toNum(v, label) {
  const n = Number(v);
  if (v === "" || v === null || v === undefined || !Number.isFinite(n)) throw new HttpError(400, label + " must be a number.");
  return n;
}

function toStr(v) {
  return v === null || v === undefined ? "" : String(v);
}

// ---------- Passwords: stored as a salted scrypt hash, never as plain text ----------
function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(password, salt, 32, { N: 16384, r: 8, p: 1 });
  return "scrypt$16384$8$1$" + salt.toString("hex") + "$" + hash.toString("hex");
}

function verifyPassword(password, stored) {
  try {
    const parts = stored.split("$");
    if (parts[0] !== "scrypt") return false;
    const salt = Buffer.from(parts[4], "hex");
    const expected = Buffer.from(parts[5], "hex");
    const actual = crypto.scryptSync(password, salt, expected.length, {
      N: Number(parts[1]), r: Number(parts[2]), p: Number(parts[3])
    });
    return crypto.timingSafeEqual(actual, expected);
  } catch (e) {
    return false;
  }
}

// ---------- Schema ----------
const SCHEMA = `
  CREATE TABLE IF NOT EXISTS roles (
    role_id   INTEGER PRIMARY KEY,
    role_name TEXT NOT NULL UNIQUE
  );
  INSERT OR IGNORE INTO roles (role_id, role_name) VALUES (1, 'admin'), (2, 'staff');

  CREATE TABLE IF NOT EXISTS users (
    user_id        INTEGER PRIMARY KEY,
    role_id        INTEGER NOT NULL REFERENCES roles (role_id) ON UPDATE CASCADE,
    full_name      TEXT NOT NULL,
    username       TEXT NOT NULL,
    password_hash  TEXT NOT NULL,
    account_status TEXT NOT NULL DEFAULT 'active' CHECK (account_status IN ('active', 'inactive')),
    created_at     TEXT NOT NULL
  );
  CREATE UNIQUE INDEX IF NOT EXISTS ux_users_username
    ON users (username COLLATE NOCASE) WHERE account_status = 'active';

  CREATE TABLE IF NOT EXISTS products (
    product_id    INTEGER PRIMARY KEY,
    product_name  TEXT NOT NULL,
    category      TEXT NOT NULL DEFAULT '',
    price         REAL NOT NULL CHECK (price >= 0),
    initial_stock INTEGER NOT NULL CHECK (initial_stock >= 0),
    current_stock INTEGER NOT NULL CHECK (current_stock >= 0),
    expiry_date   TEXT NOT NULL DEFAULT '',
    description   TEXT NOT NULL DEFAULT '',
    status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    created_at    TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS qr_codes (
    qr_code_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id   INTEGER NOT NULL REFERENCES products (product_id) ON UPDATE CASCADE ON DELETE CASCADE,
    qr_code_data TEXT NOT NULL,
    created_at   TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive'))
  );
  CREATE UNIQUE INDEX IF NOT EXISTS ux_qr_product ON qr_codes (product_id);
  CREATE UNIQUE INDEX IF NOT EXISTS ux_qr_active_data ON qr_codes (qr_code_data) WHERE status = 'active';

  CREATE TABLE IF NOT EXISTS stock_in (
    stock_in_id INTEGER PRIMARY KEY,
    product_id  INTEGER NOT NULL REFERENCES products (product_id) ON UPDATE CASCADE,
    quantity    INTEGER NOT NULL CHECK (quantity > 0),
    date        TEXT NOT NULL,
    user_id     INTEGER REFERENCES users (user_id) ON UPDATE CASCADE,
    notes       TEXT NOT NULL DEFAULT ''
  );

  CREATE TABLE IF NOT EXISTS stock_out (
    stock_out_id INTEGER PRIMARY KEY,
    product_id   INTEGER NOT NULL REFERENCES products (product_id) ON UPDATE CASCADE,
    quantity     INTEGER NOT NULL CHECK (quantity > 0),
    date         TEXT NOT NULL,
    user_id      INTEGER REFERENCES users (user_id) ON UPDATE CASCADE,
    notes        TEXT NOT NULL DEFAULT ''
  );

  CREATE TABLE IF NOT EXISTS purchase_confirmations (
    confirmation_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id          INTEGER NOT NULL REFERENCES products (product_id) ON UPDATE CASCADE,
    quantity            INTEGER NOT NULL CHECK (quantity > 0),
    confirmation_status TEXT NOT NULL CHECK (confirmation_status IN ('YES', 'NO')),
    user_id             INTEGER REFERENCES users (user_id) ON UPDATE CASCADE,
    confirmed_at        TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS expiration_records (
    expiration_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id        INTEGER NOT NULL UNIQUE REFERENCES products (product_id) ON UPDATE CASCADE ON DELETE CASCADE,
    expiry_date       TEXT NOT NULL,
    expiration_status TEXT NOT NULL CHECK (expiration_status IN ('good', 'near_expiry', 'expired')),
    checked_at        TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS activity_logs (
    log_id      INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id     INTEGER REFERENCES users (user_id) ON UPDATE CASCADE,
    action      TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id   INTEGER,
    created_at  TEXT NOT NULL
  );

  CREATE INDEX IF NOT EXISTS idx_stock_in_product  ON stock_in (product_id);
  CREATE INDEX IF NOT EXISTS idx_stock_out_product ON stock_out (product_id);
  CREATE INDEX IF NOT EXISTS idx_logs_created      ON activity_logs (created_at);

  -- Reports (SRS: "stores or generates summarized ... information"): generated live by views
  CREATE VIEW IF NOT EXISTS report_inventory AS
    SELECT p.product_id, q.qr_code_data AS product_code, p.product_name, p.category, p.price,
           p.initial_stock, p.current_stock, ROUND(p.price * p.current_stock, 2) AS stock_value,
           p.expiry_date, e.expiration_status
    FROM products p
    LEFT JOIN qr_codes q ON q.product_id = p.product_id
    LEFT JOIN expiration_records e ON e.product_id = p.product_id
    WHERE p.status = 'active';

  CREATE VIEW IF NOT EXISTS report_stock_movements AS
    SELECT 'IN' AS movement_type, s.stock_in_id AS movement_id, s.product_id, q.qr_code_data AS product_code,
           p.product_name, s.quantity, s.date, u.full_name AS recorded_by, s.notes
    FROM stock_in s
    JOIN products p ON p.product_id = s.product_id
    LEFT JOIN qr_codes q ON q.product_id = s.product_id
    LEFT JOIN users u ON u.user_id = s.user_id
    UNION ALL
    SELECT 'OUT', s.stock_out_id, s.product_id, q.qr_code_data,
           p.product_name, s.quantity, s.date, u.full_name, s.notes
    FROM stock_out s
    JOIN products p ON p.product_id = s.product_id
    LEFT JOIN qr_codes q ON q.product_id = s.product_id
    LEFT JOIN users u ON u.user_id = s.user_id;

  CREATE VIEW IF NOT EXISTS report_expiration AS
    SELECT p.product_id, q.qr_code_data AS product_code, p.product_name, p.current_stock,
           e.expiry_date, e.expiration_status, e.checked_at,
           CAST(ROUND(julianday(e.expiry_date) - julianday(date('now', 'localtime'))) AS INTEGER) AS days_left
    FROM expiration_records e
    JOIN products p ON p.product_id = e.product_id
    LEFT JOIN qr_codes q ON q.product_id = p.product_id
    WHERE p.status = 'active';
`;

// ---------- Transactions: all-or-nothing ----------
function tx(fn) {
  db.exec("BEGIN");
  try {
    const result = fn();
    db.exec("COMMIT");
    return result;
  } catch (e) {
    try { db.exec("ROLLBACK"); } catch (ignore) { /* nothing to roll back */ }
    throw friendly(e);
  }
}

// Turn database errors into short, readable messages
function friendly(e) {
  if (e instanceof HttpError) return e;
  const msg = String(e && e.message || e);
  if (/UNIQUE constraint failed: .*username/i.test(msg) || /ux_users_username/i.test(msg)) return new HttpError(400, "That username is already taken.");
  if (/qr_code_data|ux_qr_active_data/i.test(msg)) return new HttpError(400, "That product code is already used.");
  if (/UNIQUE constraint failed/i.test(msg)) return new HttpError(400, "Duplicate value: " + msg);
  if (/CHECK constraint failed/i.test(msg)) return new HttpError(400, "Invalid value (for example negative stock or quantity): " + msg);
  if (/FOREIGN KEY constraint failed/i.test(msg)) return new HttpError(400, "A related record was not found.");
  return new HttpError(400, msg);
}

// ---------- Activity logs ----------
function addLog(userId, action, entityType, entityId) {
  db.prepare("INSERT INTO activity_logs (user_id, action, entity_type, entity_id, created_at) VALUES (?, ?, ?, ?, ?)")
    .run(userId === undefined ? null : userId, action, entityType, entityId === undefined ? null : entityId, nowIso());
}

// ---------- Expiration records ----------
function expiryStatus(expiryDate) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(expiryDate)) return null;
  const parts = expiryDate.split("-").map(Number);
  const expiry = new Date(parts[0], parts[1] - 1, parts[2]);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const daysLeft = Math.round((expiry - today) / (1000 * 60 * 60 * 24));
  if (daysLeft < 0) return "expired";
  if (daysLeft <= NEAR_EXPIRY_DAYS) return "near_expiry";
  return "good";
}

let lastExpiryDay = "";

function refreshExpirations() {
  const now = nowIso();
  const products = db.prepare("SELECT product_id, expiry_date FROM products WHERE status = 'active'").all();
  const find = db.prepare("SELECT expiration_id FROM expiration_records WHERE product_id = ?");
  const insert = db.prepare("INSERT INTO expiration_records (product_id, expiry_date, expiration_status, checked_at) VALUES (?, ?, ?, ?)");
  const update = db.prepare("UPDATE expiration_records SET expiry_date = ?, expiration_status = ?, checked_at = ? WHERE product_id = ?");
  const remove = db.prepare("DELETE FROM expiration_records WHERE product_id = ?");

  products.forEach(p => {
    const status = expiryStatus(p.expiry_date);
    if (!status) { remove.run(p.product_id); return; }
    if (find.get(p.product_id)) update.run(p.expiry_date, status, now, p.product_id);
    else insert.run(p.product_id, p.expiry_date, status, now);
  });
  db.exec("DELETE FROM expiration_records WHERE product_id IN (SELECT product_id FROM products WHERE status <> 'active')");
  lastExpiryDay = localDay();
}

function refreshExpirationsIfNewDay() {
  if (lastExpiryDay !== localDay()) tx(refreshExpirations);
}

// ---------- Ids of removed users/products may be reused by the website: move the old row out of the way ----------
function rekeyRemoved(table, idCol, incomingIds, existingById) {
  let maxId = db.prepare("SELECT COALESCE(MAX(" + idCol + "), 0) AS m FROM " + table).get().m;
  incomingIds.forEach(id => { if (id > maxId) maxId = id; });
  let moved = false;
  incomingIds.forEach(id => {
    const old = existingById.get(id);
    if (old && old.inactive) {
      maxId += 1;
      db.prepare("UPDATE " + table + " SET " + idCol + " = ? WHERE " + idCol + " = ?").run(maxId, id);
      moved = true;
    }
  });
  return moved;
}

// =====================================================
// SAVING (the website sends whole lists; we compare them with the database)
// =====================================================

// ---------- Users ----------
function syncUsers(rows, actorId, opts) {
  if (!Array.isArray(rows)) throw new HttpError(400, "Users must be a list.");
  const importing = !!opts.importing;
  const roles = new Map(db.prepare("SELECT role_id, role_name FROM roles").all().map(r => [r.role_name, r.role_id]));

  const seen = new Set();
  const clean = rows.map(r => {
    const id = toInt(r.id, "User id");
    if (seen.has(id)) throw new HttpError(400, "Duplicate user id " + id + ".");
    seen.add(id);
    const name = toStr(r.name).trim();
    const username = toStr(r.username).trim();
    if (!name) throw new HttpError(400, "Full name is required.");
    if (!username) throw new HttpError(400, "Username is required.");
    const roleId = roles.get(toStr(r.role));
    if (!roleId) throw new HttpError(400, "Role must be admin or staff.");
    return { id, name, username, roleId, password: toStr(r.password) };
  });

  if (!clean.some(u => u.roleId === roles.get("admin"))) throw new HttpError(400, "There must be at least one Administrator.");
  if (actorId && !seen.has(actorId)) throw new HttpError(400, "You cannot delete your own account.");

  // 1) users that are no longer in the list are deactivated (never erased, so history keeps its link)
  const activeNow = db.prepare("SELECT user_id FROM users WHERE account_status = 'active'").all();
  activeNow.forEach(u => {
    if (!seen.has(u.user_id)) {
      db.prepare("UPDATE users SET account_status = 'inactive' WHERE user_id = ?").run(u.user_id);
      dropSessionsFor(u.user_id);
      if (!importing) addLog(actorId, "USER_REMOVED", "user", u.user_id);
    }
  });

  // 2) a new user may reuse the id of a removed one
  let existing = new Map(db.prepare("SELECT * FROM users").all().map(r => [r.user_id, { row: r, inactive: r.account_status !== "active" }]));
  const asFlags = new Map([...existing].map(([id, v]) => [id, { inactive: v.inactive }]));
  if (rekeyRemoved("users", "user_id", seen, asFlags)) {
    existing = new Map(db.prepare("SELECT * FROM users").all().map(r => [r.user_id, { row: r, inactive: r.account_status !== "active" }]));
  }

  // 3) add / update
  clean.forEach(u => {
    const old = existing.get(u.id);
    if (old && !old.inactive) {
      const row = old.row;
      const changed = row.full_name !== u.name || row.username !== u.username || row.role_id !== u.roleId;
      const passwordChanged = u.password !== "" && !verifyPassword(u.password, row.password_hash);
      if (changed || passwordChanged) {
        db.prepare("UPDATE users SET full_name = ?, username = ?, role_id = ?, password_hash = ? WHERE user_id = ?")
          .run(u.name, u.username, u.roleId, passwordChanged ? hashPassword(u.password) : row.password_hash, u.id);
        if (changed && row.role_id !== u.roleId) dropSessionsFor(u.id);
        if (!importing) addLog(actorId, "USER_UPDATED", "user", u.id);
      }
    } else {
      if (!u.password) throw new HttpError(400, "Password is required for a new user.");
      db.prepare("INSERT INTO users (user_id, role_id, full_name, username, password_hash, account_status, created_at) VALUES (?, ?, ?, ?, ?, 'active', ?)")
        .run(u.id, u.roleId, u.name, u.username, hashPassword(u.password), nowIso());
      if (!importing) addLog(actorId, "USER_ADDED", "user", u.id);
    }
  });
}

// ---------- Products (+ their QR code and expiration record) ----------
function syncProducts(rows, actorId, opts) {
  if (!Array.isArray(rows)) throw new HttpError(400, "Products must be a list.");
  const importing = !!opts.importing;
  const staff = !!opts.staff;
  const denied = () => new HttpError(403, "Only an Administrator can add, edit or delete products.");

  const seen = new Set();
  const codes = new Set();
  const clean = rows.map(r => {
    const id = toInt(r.id, "Product id");
    if (seen.has(id)) throw new HttpError(400, "Duplicate product id " + id + ".");
    seen.add(id);
    const code = toStr(r.code).trim();
    const name = toStr(r.name).trim();
    if (!code) throw new HttpError(400, "Product code is required.");
    if (!name) throw new HttpError(400, "Product name is required.");
    if (codes.has(code.toLowerCase())) throw new HttpError(400, "That product code is already used.");
    codes.add(code.toLowerCase());
    return {
      id, code, name,
      category: toStr(r.category).trim(),
      price: toNum(r.price, "Price"),
      initialStock: toInt(r.initialStock, "Initial stock"),
      currentStock: toInt(r.currentStock, "Current stock"),
      expiryDate: toStr(r.expiryDate),
      description: toStr(r.description)
    };
  });

  const load = () => new Map(db.prepare(
    "SELECT p.*, q.qr_code_data AS code FROM products p LEFT JOIN qr_codes q ON q.product_id = p.product_id"
  ).all().map(r => [r.product_id, r]));

  // 1) products that are no longer in the list are marked inactive (kept for stock history)
  load().forEach((p, id) => {
    if (p.status === "active" && !seen.has(id)) {
      if (staff) throw denied();
      db.prepare("UPDATE products SET status = 'inactive' WHERE product_id = ?").run(id);
      db.prepare("UPDATE qr_codes SET status = 'inactive' WHERE product_id = ?").run(id);
      if (!importing) addLog(actorId, "PRODUCT_REMOVED", "product", id);
    }
  });

  // 2) a new product may reuse the id of a removed one
  let existing = load();
  const flags = new Map([...existing].map(([id, p]) => [id, { inactive: p.status !== "active" }]));
  if (rekeyRemoved("products", "product_id", seen, flags)) existing = load();

  // 3) add / update
  clean.forEach(p => {
    const old = existing.get(p.id);
    if (old && old.status === "active") {
      const detailsChanged =
        old.product_name !== p.name || old.category !== p.category || old.price !== p.price ||
        old.initial_stock !== p.initialStock || old.expiry_date !== p.expiryDate ||
        old.description !== p.description || old.code !== p.code;
      if (detailsChanged && staff) throw denied();

      db.prepare("UPDATE products SET product_name = ?, category = ?, price = ?, initial_stock = ?, current_stock = ?, expiry_date = ?, description = ? WHERE product_id = ?")
        .run(p.name, p.category, p.price, p.initialStock, p.currentStock, p.expiryDate, p.description, p.id);
      if (old.code !== p.code) db.prepare("UPDATE qr_codes SET qr_code_data = ? WHERE product_id = ?").run(p.code, p.id);
      if (detailsChanged && !importing) addLog(actorId, "PRODUCT_UPDATED", "product", p.id);
    } else {
      if (staff) throw denied();
      db.prepare("INSERT INTO products (product_id, product_name, category, price, initial_stock, current_stock, expiry_date, description, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', ?)")
        .run(p.id, p.name, p.category, p.price, p.initialStock, p.currentStock, p.expiryDate, p.description, nowIso());
      if (!importing) addLog(actorId, "PRODUCT_ADDED", "product", p.id);
    }
    if (!db.prepare("SELECT 1 FROM qr_codes WHERE product_id = ?").get(p.id)) {
      db.prepare("INSERT INTO qr_codes (product_id, qr_code_data, created_at, status) VALUES (?, ?, ?, 'active')").run(p.id, p.code, nowIso());
    }
  });

  refreshExpirations();
}

// ---------- Stock-In / Stock-Out (history is only ever added to, never erased) ----------
const placeholderUsers = new Map();

function userIdForName(name, actorId, importing) {
  const clean = toStr(name).trim();
  if (clean) {
    const match = db.prepare("SELECT user_id FROM users WHERE full_name = ? AND account_status = 'active' ORDER BY user_id LIMIT 1").get(clean);
    if (match) return match.user_id;
  }
  if (actorId) return actorId;
  if (!importing) return null;

  // Old history that points to a user who no longer exists: keep the name on an inactive account
  const label = clean || "Unknown";
  if (placeholderUsers.has(label)) return placeholderUsers.get(label);
  const maxId = db.prepare("SELECT COALESCE(MAX(user_id), 0) AS m FROM users").get().m + 1;
  db.prepare("INSERT INTO users (user_id, role_id, full_name, username, password_hash, account_status, created_at) VALUES (?, 2, ?, ?, ?, 'inactive', ?)")
    .run(maxId, label, "removed-user-" + maxId, hashPassword(crypto.randomBytes(16).toString("hex")), nowIso());
  placeholderUsers.set(label, maxId);
  return maxId;
}

function syncMovements(rows, actorId, opts) {
  if (!Array.isArray(rows)) throw new HttpError(400, "Movements must be a list.");
  const importing = !!opts.importing;

  const inIds = new Set(db.prepare("SELECT stock_in_id AS id FROM stock_in").all().map(r => r.id));
  const outIds = new Set(db.prepare("SELECT stock_out_id AS id FROM stock_out").all().map(r => r.id));
  const productIds = new Set(db.prepare("SELECT product_id AS id FROM products").all().map(r => r.id));
  const seen = new Set();

  rows.forEach(m => {
    const id = toInt(m.id, "Movement id");
    if (seen.has(id)) throw new HttpError(400, "Duplicate movement id " + id + ".");
    seen.add(id);

    const type = toStr(m.type);
    if (type !== "IN" && type !== "OUT") throw new HttpError(400, "Movement type must be IN or OUT.");
    const exists = type === "IN" ? inIds.has(id) : outIds.has(id);
    if (exists) return;                                            // already saved: history never changes
    if (inIds.has(id) || outIds.has(id)) throw new HttpError(400, "Movement id " + id + " is already used.");

    const productId = toInt(m.productId, "Product id");
    if (!productIds.has(productId)) throw new HttpError(400, "Product not found for this movement.");
    const quantity = toInt(m.quantity, "Quantity");
    const date = toStr(m.date);
    if (!date) throw new HttpError(400, "Movement date is required.");
    const userId = userIdForName(m.user, actorId, importing);
    const notes = toStr(m.remarks);

    if (type === "IN") {
      db.prepare("INSERT INTO stock_in (stock_in_id, product_id, quantity, date, user_id, notes) VALUES (?, ?, ?, ?, ?, ?)")
        .run(id, productId, quantity, date, userId, notes);
      if (!importing) addLog(actorId, "STOCK_IN", "stock_in", id);
    } else {
      db.prepare("INSERT INTO stock_out (stock_out_id, product_id, quantity, date, user_id, notes) VALUES (?, ?, ?, ?, ?, ?)")
        .run(id, productId, quantity, date, userId, notes);
      if (!importing) addLog(actorId, "STOCK_OUT", "stock_out", id);
    }
  });
}

// ---------- Public save functions ----------
function saveKey(key, rows, actor) {
  if (key === "users" && actor.role !== "admin") throw new HttpError(403, "Only an Administrator can manage users.");
  return tx(() => {
    if (key === "users") syncUsers(rows, actor.userId, {});
    else if (key === "products") syncProducts(rows, actor.userId, { staff: actor.role !== "admin" });
    else if (key === "movements") syncMovements(rows, actor.userId, {});
    else throw new HttpError(400, "Unknown key.");
  });
}

// Stock-In / Stock-Out: the new stock level and the movement are saved together, or not at all
function saveBatch(body, actor) {
  if (!body || typeof body !== "object") throw new HttpError(400, "Invalid data.");
  return tx(() => {
    if (body.products !== undefined) syncProducts(body.products, actor.userId, { staff: actor.role !== "admin" });
    if (body.movements !== undefined) syncMovements(body.movements, actor.userId, {});
  });
}

// ---------- QR scan: YES / NO purchase confirmation ----------
function addConfirmation(body, actor) {
  const productId = toInt(body && body.productId, "Product id");
  const quantity = toInt(body && body.quantity, "Quantity");
  const status = toStr(body && body.status).toUpperCase();
  if (status !== "YES" && status !== "NO") throw new HttpError(400, "Status must be YES or NO.");
  return tx(() => {
    if (!db.prepare("SELECT 1 FROM products WHERE product_id = ?").get(productId)) throw new HttpError(400, "Product not found.");
    const result = db.prepare("INSERT INTO purchase_confirmations (product_id, quantity, confirmation_status, user_id, confirmed_at) VALUES (?, ?, ?, ?, ?)")
      .run(productId, quantity, status, actor.userId, nowIso());
    const id = Number(result.lastInsertRowid);
    addLog(actor.userId, status === "YES" ? "PURCHASE_CONFIRMED" : "PURCHASE_DECLINED", "purchase_confirmation", id);
    return id;
  });
}

// =====================================================
// READING (same shape the website already uses)
// =====================================================
function loadAll(actor) {
  refreshExpirationsIfNewDay();

  const users = actor.role === "admin"
    ? db.prepare(`SELECT u.user_id AS id, u.full_name AS name, u.username, r.role_name AS role
                  FROM users u JOIN roles r ON r.role_id = u.role_id
                  WHERE u.account_status = 'active' ORDER BY u.user_id`).all()
    : [];

  const products = db.prepare(`SELECT p.product_id AS id, q.qr_code_data AS code, p.product_name AS name, p.category, p.price,
                                      p.initial_stock AS initialStock, p.current_stock AS currentStock,
                                      p.expiry_date AS expiryDate, p.description
                               FROM products p
                               LEFT JOIN qr_codes q ON q.product_id = p.product_id
                               WHERE p.status = 'active' ORDER BY p.product_id`).all();

  const movements = db.prepare(`SELECT m.id, m.productId, q.qr_code_data AS code, p.product_name AS name, m.type, m.quantity,
                                       m.notes AS remarks, COALESCE(u.full_name, '') AS user, m.date
                                FROM (
                                  SELECT stock_in_id AS id, product_id AS productId, 'IN' AS type, quantity, notes, user_id, date FROM stock_in
                                  UNION ALL
                                  SELECT stock_out_id, product_id, 'OUT', quantity, notes, user_id, date FROM stock_out
                                ) m
                                JOIN products p ON p.product_id = m.productId
                                LEFT JOIN qr_codes q ON q.product_id = m.productId
                                LEFT JOIN users u ON u.user_id = m.user_id
                                ORDER BY m.id`).all();

  return {
    users: users.map(r => ({ ...r })),
    products: products.map(r => ({ ...r })),
    movements: movements.map(r => ({ ...r }))
  };
}

// =====================================================
// LOGIN SESSIONS (kept in memory; everyone logs in again after the server restarts)
// =====================================================
const sessions = new Map();

function dropSessionsFor(userId) {
  sessions.forEach((s, token) => { if (s.userId === userId) sessions.delete(token); });
}

function login(username, password) {
  const user = db.prepare(`SELECT u.*, r.role_name FROM users u JOIN roles r ON r.role_id = u.role_id
                           WHERE u.username = ? AND u.account_status = 'active'`).get(toStr(username).trim());
  // Always do the same amount of work so a wrong username is not faster than a wrong password
  const hash = user ? user.password_hash : "scrypt$16384$8$1$00000000000000000000000000000000$" + "00".repeat(32);
  const ok = verifyPassword(toStr(password), hash);
  if (!user || !ok) return null;

  const token = crypto.randomBytes(32).toString("hex");
  sessions.set(token, {
    userId: user.user_id, role: user.role_name, name: user.full_name, username: user.username,
    expires: Date.now() + SESSION_HOURS * 3600 * 1000
  });
  addLog(user.user_id, "LOGIN", "user", user.user_id);
  return { token, user: { name: user.full_name, username: user.username, role: user.role_name } };
}

function getSession(token) {
  const s = sessions.get(token);
  if (!s) return null;
  if (s.expires < Date.now()) { sessions.delete(token); return null; }
  s.expires = Date.now() + SESSION_HOURS * 3600 * 1000;   // stays alive while in use

  // keep name/role in sync with the database
  const u = db.prepare("SELECT u.full_name, u.username, u.account_status, r.role_name FROM users u JOIN roles r ON r.role_id = u.role_id WHERE u.user_id = ?").get(s.userId);
  if (!u || u.account_status !== "active") { sessions.delete(token); return null; }
  s.name = u.full_name; s.username = u.username; s.role = u.role_name;
  return s;
}

function logout(token) {
  const s = sessions.get(token);
  if (s) {
    try { addLog(s.userId, "LOGOUT", "user", s.userId); } catch (e) { /* ignore */ }
    sessions.delete(token);
  }
}

// =====================================================
// BACKUPS (SRS 5.3): one automatic copy per day, the latest 14 are kept
// =====================================================
function backupNow() {
  const file = path.join(paths.backups, "pingpings-" + stamp() + ".db");
  db.exec("VACUUM INTO '" + file.replace(/'/g, "''") + "'");
  return file;
}

function dailyBackup() {
  try {
    const prefix = "pingpings-" + localDay().replace(/-/g, "") + "-";
    const files = fs.readdirSync(paths.backups).filter(f => /^pingpings-\d{8}-\d{6}\.db$/.test(f)).sort();
    if (!files.some(f => f.startsWith(prefix))) {
      backupNow();
      files.push("new");
    }
    const all = fs.readdirSync(paths.backups).filter(f => /^pingpings-\d{8}-\d{6}\.db$/.test(f)).sort();
    all.slice(0, Math.max(0, all.length - BACKUPS_TO_KEEP)).forEach(f => fs.unlinkSync(path.join(paths.backups, f)));
  } catch (e) {
    console.log("Backup skipped: " + e.message);
  }
}

// =====================================================
// OPENING THE DATABASE (creating it, or upgrading older storage)
// =====================================================
function defaultData() {
  return {
    users: [
      { id: 1, name: "Owner", username: "admin", password: "admin123", role: "admin" },
      { id: 2, name: "Staff 1", username: "staff", password: "staff123", role: "staff" }
    ],
    products: [],
    movements: []
  };
}

// The earlier 3-table SQLite version: read its data so nothing is lost
function readOldSqlite(file) {
  const old = new DatabaseSync(file);
  try {
    const version = old.prepare("PRAGMA user_version").get().user_version;
    if (version >= SCHEMA_VERSION) return { current: true };
    const tables = old.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all().map(r => r.name);
    if (!tables.includes("users") || !tables.includes("products") || !tables.includes("movements")) return { data: null };
    const data = {
      users: old.prepare("SELECT id, name, username, password, role FROM users ORDER BY position, id").all(),
      products: old.prepare("SELECT id, code, name, category, price, initial_stock, current_stock, expiry_date, description FROM products ORDER BY position, id").all()
        .map(r => ({ id: r.id, code: r.code, name: r.name, category: r.category, price: r.price,
                     initialStock: r.initial_stock, currentStock: r.current_stock, expiryDate: r.expiry_date, description: r.description })),
      movements: old.prepare("SELECT id, product_id, code, name, type, quantity, remarks, user_name, moved_at FROM movements ORDER BY position, id").all()
        .map(r => ({ id: r.id, productId: r.product_id, code: r.code, name: r.name, type: r.type,
                     quantity: r.quantity, remarks: r.remarks, user: r.user_name, date: r.moved_at }))
    };
    data.users = data.users.map(r => ({ ...r }));
    return { data };
  } catch (e) {
    return { data: null };
  } finally {
    old.close();
  }
}

function openDatabase(dataDir) {
  paths.dataDir = dataDir;
  paths.file = path.join(dataDir, "pingpings.db");
  paths.json = path.join(dataDir, "db.json");
  paths.backups = path.join(dataDir, "backups");
  fs.mkdirSync(paths.backups, { recursive: true });

  let start = null;
  let note = "";

  // An older pingpings.db (3 tables)? Keep a copy, read it, and build the new design.
  if (fs.existsSync(paths.file)) {
    const found = readOldSqlite(paths.file);
    if (!found.current) {
      fs.copyFileSync(paths.file, path.join(paths.backups, "before-upgrade-" + stamp() + ".db"));
      fs.unlinkSync(paths.file);
      start = found.data;
      note = "Your data was moved into the new database design (a copy of the old database is in data/backups).";
    }
  }

  db = new DatabaseSync(paths.file);
  db.exec("PRAGMA foreign_keys = ON;");
  const version = db.prepare("PRAGMA user_version").get().user_version;
  db.exec(SCHEMA);

  if (version < SCHEMA_VERSION) {
    let jsonImported = false;
    if (!start && fs.existsSync(paths.json)) {
      try {
        start = JSON.parse(fs.readFileSync(paths.json, "utf8"));
        jsonImported = true;
      } catch (e) {
        console.log("Could not read data/db.json, starting with default data instead.");
      }
    }
    if (!start) start = defaultData();

    try {
      tx(() => {
        syncUsers(Array.isArray(start.users) && start.users.length ? start.users : defaultData().users, null, { importing: true });
        syncProducts(Array.isArray(start.products) ? start.products : [], null, { importing: true });
        syncMovements(Array.isArray(start.movements) ? start.movements : [], null, { importing: true });
      });
    } catch (e) {
      console.error("Could not import the existing data: " + e.message);
      db.close();
      try { fs.unlinkSync(paths.file); } catch (ignore) { /* leave nothing half-made */ }
      process.exit(1);
    }
    db.exec("PRAGMA user_version = " + SCHEMA_VERSION);

    if (jsonImported) {
      fs.renameSync(paths.json, paths.json + ".imported");   // kept as a backup, never deleted
      note = "Your old data (data/db.json) was imported into the SQLite database.";
    }
  }

  tx(refreshExpirations);
  return note;
}

function closeDatabase() {
  try { db.close(); } catch (e) { /* already closed */ }
}

module.exports = {
  HttpError, openDatabase, closeDatabase, loadAll, saveKey, saveBatch, addConfirmation,
  login, logout, getSession, dailyBackup, backupNow
};
